contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: send value to addToBalance and assert balance increased by that value
    function runTest(address sender, uint256 value) public {
        // require this contract has enough ETH to forward
        require(address(this).balance >= value);
        // observe balance before
        uint256 before = c.getBalance(sender);
        // perform the state-changing call: call addToBalance from this contract, but we need msg.sender to be 'sender'
        // We cannot change msg.sender; instead we drive using this contract as the caller. So require sender == address(this)
        // to make the assertion meaningful and general, require the provided sender equals this contract
        require(sender == address(this));

        // call addToBalance sending ETH
        c.addToBalance{value: value}();

        // observe balance after
        uint256 after = c.getBalance(sender);

        // The invariant: after == before + value
        assert(after == before + value);
    }

    // allow contract to receive ETH so tests can fund it
    receive() external payable {}
}

