contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function runTest(address payable user, uint256 deposit) public payable {
        // ensure this contract has enough balance to forward deposit
        require(address(this).balance >= deposit, "insufficient balance for test");
        // deposit 'deposit' wei into C from this contract but attributing to this contract's own balance
        // we need to call addToBalance from this contract, so forward value
        c.addToBalance{value: deposit}();

        // read reported balance for this contract's address
        uint reported = c.getBalance(address(this));

        // To observe the true stored balance we perform a withdraw and see that the contract receives exactly deposit
        // First, capture balance of this contract before withdraw
        uint before = address(this).balance;
        // Call withdrawBalance which will transfer the stored balance to this contract
        c.withdrawBalance();
        uint after = address(this).balance;

        // The actual amount received should equal the stored balance that was withdrawn.
        uint received = after - before;

        // The property: the reported balance must equal the actually withdrawable amount (received).
        // This holds in original P but is violated by the mutant that returns stored+1.
        assert(reported == received);
    }

    // allow contract to receive ETH so it can forward deposits
    receive() external payable {}
}

contract InvMutTest {
