    constructor(C _c) { c = _c; }

    // single public test function
    function runTest(address user, uint256 amount) public payable {
        // must fund this contract so it can forward ETH
        require(address(this).balance >= amount, "insufficient test balance");

        // record balances before
        uint256 beforeUser = c.getBalance(user);
        uint256 beforeContract = address(c).balance;

        // perform the action: forward amount to c.addToBalance from this contract
        // use call with value by calling c.addToBalance{value: amount}()
        // the call is a top-level state-changing call
        c.addToBalance{value: amount}();

        // observe balances after
        uint256 afterUser = c.getBalance(user);
        uint256 afterContract = address(c).balance;

        // The rule: after a successful addToBalance, the user's recorded balance increases by amount
        // and the contract's balance increases by amount.
        // Note: we use msg.sender's perspective: this test calls addToBalance, so user must equal address(this)
        require(user == address(this), "user must be this contract for sent value");

        assert(afterUser == beforeUser + amount && afterContract == beforeContract + amount);
    }

    // allow funding this test contract
    receive() external payable {}
}

