pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: actor and amount. The property: after a call to addToBalance by actor
    // the reported getBalance(actor) equals the previous balance + amount (modulo uint wrap in buggy mutant).
    function testFuzz_property(address actor, uint256 amount) public {
        // keep actor non-zero to be a sensible account
        vm.assume(actor != address(0));

        // fund actor so they can send `amount` wei
        // bound amount to the available addressable ether, but keep wide (0..2**240)
        uint256 amt = bound(amount, 0, type(uint256).max);
        // ensure actor has enough ETH to send amt (deal truncates to uint128 internally in some FDs but acceptable)
        vm.deal(actor, amt);

        // read old balance stored in contract for actor
        uint256 old = c.getBalance(actor);

        // perform the payable call from actor
        bool ok;
        vm.prank(actor);
        try c.addToBalance{value: amt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful call on the reference, the stored balance must equal old + amt.
        // For the reference contract this holds for ALL inputs; the mutant (which removes the require overflow check)
        // can cause wraparound making getBalance(actor) != old + amt for some inputs — the fuzzer will find such.
        uint256 newBal = c.getBalance(actor);

        // Single assertion: when the call succeeded, newBal == old + amt
        // (if the call reverted, the reference also would revert only on overflow check; but reference never reverts
        // for admissible inputs — we assert on successful call case to capture the logical rule)
        if (ok) {
            assertTrue(newBal == old + amt);
        } else {
            // If the call reverted, then the reference would only revert on an overflow check; however the reference's
            // intended rule is expressed for successful completion. To keep a single assertTrue as required, we assert
            // a tautology in the revert branch by converting to equivalent condition: newBal == old (since no change on revert).
            // This still reads c's public getter.
            assertTrue(newBal == old);
        }
    }
}

